import{_ as t,o as n,c as a,a0 as i}from"./chunks/framework.D7EjqxMK.js";const g=JSON.parse('{"title":"Spec-Driven Development (Spec Coding) 概述","description":"","frontmatter":{},"headers":[],"relativePath":"07-ai-coding/03_spec_coding/01_Spec_Coding概述.md","filePath":"07-ai-coding/03_spec_coding/01_Spec_Coding概述.md"}'),r={name:"07-ai-coding/03_spec_coding/01_Spec_Coding概述.md"};function o(d,e,l,s,p,c){return n(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="spec-driven-development-spec-coding-概述" tabindex="-1">Spec-Driven Development (Spec Coding) 概述 <a class="header-anchor" href="#spec-driven-development-spec-coding-概述" aria-label="Permalink to &quot;Spec-Driven Development (Spec Coding) 概述&quot;">​</a></h1><blockquote><p><strong>在知识图谱中的位置</strong>：模块三 · 03_spec_coding · 第 1 节 <strong>难度</strong>：⭐⭐⭐</p></blockquote><hr><h2 id="_1-概念" tabindex="-1">1. 概念 <a class="header-anchor" href="#_1-概念" aria-label="Permalink to &quot;1. 概念&quot;">​</a></h2><p><strong>Spec-Driven Development (SDD)</strong> 是一种先编写详细规格文档（PRD），再由 AI 按规格生成代码的开发方式。它是 Vibe Coding 的对照范式。</p><h3 id="sdd-vs-vibe-coding-核心对比" tabindex="-1">SDD vs Vibe Coding 核心对比 <a class="header-anchor" href="#sdd-vs-vibe-coding-核心对比" aria-label="Permalink to &quot;SDD vs Vibe Coding 核心对比&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Vibe Coding:    对话 → AI 生成代码 → 迭代调整</span></span>
<span class="line"><span>Spec Coding:    PRD (详细规格) → AI 按规格生成代码 → 验证</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Vibe: 灵活但不可控</span></span>
<span class="line"><span>Spec: 规范但高效</span></span></code></pre></div><hr><h2 id="_2-spec-driven-development-的核心模式" tabindex="-1">2. Spec-Driven Development 的核心模式 <a class="header-anchor" href="#_2-spec-driven-development-的核心模式" aria-label="Permalink to &quot;2. Spec-Driven Development 的核心模式&quot;">​</a></h2><h3 id="模式一-prd-first" tabindex="-1">模式一：PRD-First <a class="header-anchor" href="#模式一-prd-first" aria-label="Permalink to &quot;模式一：PRD-First&quot;">​</a></h3><ol><li>编写详细的 PRD（包含技术栈、API、Schema、文件结构）</li><li>将 PRD 作为提示输入给 AI Agent</li><li>AI Agent 按 PRD 生成代码</li><li>人工审查 + 修改</li></ol><h3 id="模式二-bdd-spec" tabindex="-1">模式二：BDD + Spec <a class="header-anchor" href="#模式二-bdd-spec" aria-label="Permalink to &quot;模式二：BDD + Spec&quot;">​</a></h3><ol><li>将需求转化为 Behavior-Driven Development (BDD) 格式</li><li>用 BDD 的 Given/When/Then 作为 Prompt</li><li>AI 生成测试和实现代码</li></ol><h3 id="模式三-living-spec" tabindex="-1">模式三：Living Spec <a class="header-anchor" href="#模式三-living-spec" aria-label="Permalink to &quot;模式三：Living Spec&quot;">​</a></h3><ol><li>PRD 不是静态文档，而是持续更新的&quot;活文档&quot;</li><li>随着开发进展，PRD 更新</li><li>AI Agent 根据最新 PRD 重新生成代码</li></ol><hr><h2 id="_3-spec-driven-development-的优势" tabindex="-1">3. Spec-Driven Development 的优势 <a class="header-anchor" href="#_3-spec-driven-development-的优势" aria-label="Permalink to &quot;3. Spec-Driven Development 的优势&quot;">​</a></h2><table tabindex="0"><thead><tr><th>优势</th><th>说明</th></tr></thead><tbody><tr><td><strong>可预测性</strong></td><td>代码完全按规格生成</td></tr><tr><td><strong>可测试性</strong></td><td>规格即测试标准</td></tr><tr><td><strong>可追溯性</strong></td><td>需求到代码的映射清晰</td></tr><tr><td><strong>团队协作</strong></td><td>PRD 作为对齐工具</td></tr><tr><td><strong>生产就绪</strong></td><td>代码经过规格验证</td></tr></tbody></table><hr><h2 id="_4-spec-driven-development-的适用场景" tabindex="-1">4. Spec-Driven Development 的适用场景 <a class="header-anchor" href="#_4-spec-driven-development-的适用场景" aria-label="Permalink to &quot;4. Spec-Driven Development 的适用场景&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>适合度</th></tr></thead><tbody><tr><td>生产代码</td><td>⭐⭐⭐⭐⭐</td></tr><tr><td>团队协作</td><td>⭐⭐⭐⭐⭐</td></tr><tr><td>复杂系统架构</td><td>⭐⭐⭐⭐⭐</td></tr><tr><td>长期维护项目</td><td>⭐⭐⭐⭐⭐</td></tr><tr><td>安全敏感系统</td><td>⭐⭐⭐⭐⭐</td></tr><tr><td>快速原型</td><td>⭐⭐⭐</td></tr><tr><td>个人项目</td><td>⭐⭐⭐</td></tr></tbody></table><hr><h2 id="_5-参考资料" tabindex="-1">5. 参考资料 <a class="header-anchor" href="#_5-参考资料" aria-label="Permalink to &quot;5. 参考资料&quot;">​</a></h2><ul><li><a href="https://www.augmentcode.com/guides/vibe-coding-vs-spec-driven-development" target="_blank" rel="noreferrer">Vibe Coding vs Spec-Driven Development (Augment Code)</a></li><li><a href="https://zencoder.ai/blog/spec-driven-development-vs-vibe-coding" target="_blank" rel="noreferrer">Spec-Driven Development vs. Vibe Coding (zencoder.ai)</a></li><li><a href="https://pockit.tools/blog/specification-driven-development-ai-coding-agents-complete-guide/" target="_blank" rel="noreferrer">Specification-Driven Development (pockit.tools)</a></li><li><a href="https://www.bradjolicoeur.com/article/ai-software-engineering-vibe-spec-prompting" target="_blank" rel="noreferrer">Master AI in Software Engineering: Vibe vs. Spec Coding (bradjolicoeur.com)</a></li><li><a href="https://blog.appxlab.io/2026/03/27/spec-driven-development-ai-coding/" target="_blank" rel="noreferrer">Spec-Driven Development: Stop Vibe Coding, Ship Real Code (appxlab.io)</a></li><li><a href="https://www.javacodegeeks.com/2026/03/spec-driven-developmentwith-ai-coding-agents-the-workflow-replacingprompt-and-pray.html" target="_blank" rel="noreferrer">Spec-Driven Development with AI Coding Agents (javacodegeeks.com)</a></li></ul>`,24)])])}const v=t(r,[["render",o]]);export{g as __pageData,v as default};
